from collections import defaultdict
from recover import T,W
facets = [['by-type/waf-bypass.md', '放行页面与脚本执行需要分别观察', '两图分别展示被阻断页面与变更查询后正常首页，未展示反射或脚本执行。\n\n固定路径、身份和输入上下文，核最终字节、过滤层及应用消费者。页面恢复可达只说明这组请求的处置变化，不能推广为通用 WAF 绕过或已成立 XSS。\n\n来源：[保存帖1](https://x.com/i/status/1528390423655464962)。'], ['by-type/idor-access-control.md', '未发布功能可见要核服务端动作而非界面开关', '正文询问未发布功能是否算漏洞，另一图链接摘要提到用 match/replace 显示隐藏功能。\n\n区分前端开关、文档入口、请求可达和服务端授权。用自有不同角色核同一动作与最终状态；显示按钮不等于拥有功能权限，未公开也不自动构成漏洞。\n\n来源：[保存帖1](https://x.com/i/status/1528415663811100672)、[保存帖2](https://x.com/i/status/1531700040351494144)。'], ['by-type/file-upload.md', '上传文件名按后续消费者拆开核对', '正文把文件名中的路径、SQL、HTML 和 shell 片段连接到不同缺陷。\n\n追文件名从接收、规范化、保存到查询、页面展示和命令参数的每次使用。包含某语法只产生候选，不能自动证明会交给对应解释器；自有无害样本按单一消费者核对，区分路径变化、数据显示和执行。\n\n来源：[保存帖1](https://x.com/i/status/1528440520422604801)。'], ['hunting-strategy.md', '工具的流行程度不能代替方法适配与证据', '正文认为热门工具使发现趋同，并建议学习工具而非跟随多数。\n\n按功能、身份、输入类型、环境和证据输出选方法，记录工具能覆盖及漏掉的部分。热门或小众均不保证效果，学习清单也不计作目标覆盖；优先解决当前消费者与业务状态的不确定性。\n\n来源：[保存帖1](https://x.com/i/status/1528471256013721600)、[保存帖2](https://x.com/i/status/1530888110011297793)。'], ['discovery/records-and-incremental.md', 'Recon 管道需核工具输入类型与输出是否进入合并', '正文将根域收集、HTTP、模板、截图和归档连接；部分命令把 URL 当域名，或用管道连接未必消费 stdin 的收集器。\n\n在离线样本核实际输入接口、退出状态和产物格式，给每阶段保留候选映射。管道连通不代表上游结果被下游使用，状态筛选和去重也会丢失候选；不把整串命令完成当全量覆盖。\n\n来源：[保存帖1](https://x.com/i/status/1528540317305057280)、[保存帖2](https://x.com/i/status/1530021852890152960)。'], ['by-type/subdomain-takeover.md', 'CNAME 链与可注册域名仍需核受影响消费者', '终端展示多级 CNAME，正文建议检查目标域是否可购买。\n\n保留别名链、TTL、当前登记与服务消费者，区分记录存在、悬空、可认领和实际控制内容。域名可注册不等于已接管原服务，也不授予购买许可；不在资料提炼中注册域名。\n\n来源：[保存帖1](https://x.com/i/status/1528665803414855681)。'], ['discovery/passive-and-services.md', '证书 WHOIS 和 Analytics 关联需保存来源区别', '图列证书、反向 WHOIS、Analytics 标识的相关域发现，并同时出现不同版本标记。\n\n记录每种关系、时间和归并规则，区分组织文本、共享跟踪代码与证书条目。相关不等于同一资产归属；版本冲突保留原文，不自动扩范围或把输出喂给主动工具。\n\n来源：[保存帖1](https://x.com/i/status/1528687407587299330)。'], ['discovery/records-and-incremental.md', '合并文件名不一致会静默漏掉子域来源', '脚本图收集多个来源，另一脚本把 subfinder 输出追加到不同单复数文件名，最后只整理其中一个文件。\n\n按阶段核输入、产物文件及实际合并集合，用自有小样本验证各来源都进入并集。追加写入会混入旧运行，排序与解析过滤也会改变候选；总行数包含重复或多阶段文件，不能等同唯一覆盖。\n\n来源：[保存帖1](https://x.com/i/status/1528763664991387650)、[保存帖2](https://x.com/i/status/1531294108852944898)。'], ['experiment-design.md', 'wc 文件总行数不能代表唯一发现数', '终端对多个收集文件与合并文件计数并打印总数。\n\n分别记录原来源行数、归并后的唯一对象、失败和排除项。将原始文件与合并产物一起相加会重复计数；行数也不说明解析、当前可达或业务已验证。\n\n来源：[保存帖1](https://x.com/i/status/1528763664991387650)。'], ['by-type/idor-access-control.md', '双斜杠状态差异需核规范化后的同一入口', '正文展示登录路径 403 与双斜杠路径 200。\n\n固定主体与请求条件，比较代理/框架规范化路径、处理器和最终响应。200 可能是另一公共页或错误页；只有原受限动作在不足权限下成功，才支持授权差异。\n\n来源：[保存帖1](https://x.com/i/status/1528796861020405761)。'], ['discovery/passive-and-services.md', '反向 IP 与云提供商网段不自动属于租户', '正文建议由 IP 索引与 BGP 查询寻找资产，图显示长搜索查询遭截断。\n\n保留索引条件、时间、分配对象和当前归属证据。共享云 IP/ASN/CIDR 常覆盖多个租户，不能推为目标公司的完整网段；截断后的条件未必生效，历史词数提示不作为当前规则。\n\n来源：[保存帖1](https://x.com/i/status/1528818066255126528)、[保存帖2](https://x.com/i/status/1528820606103392256)、[保存帖3](https://x.com/i/status/1530142163182444546)。'], ['impact-and-acceptance.md', '严重性处理状态与奖励规则分别记录', '一图同时显示 Critical 与 Informative Closed，其他回复确认问题但按特定历史奖励规则不给金钱奖励。\n\n区分技术影响、范围、处理状态和奖励资格。平台标签或金额不能代替复现证据，不给奖励也不自动否定机制；保留当时项目条件，不推广成所有项目标准。\n\n来源：[保存帖1](https://x.com/i/status/1528869505275133952)、[保存帖2](https://x.com/i/status/1529931474216050690)。'], ['by-type/csrf.md', 'CSRF 生成器产生表单还需真实跨来源业务结果', '图展示由代理请求生成表单、Test in browser 和本地 burpsuite 展示 URL。\n\n核生成后的方法、字段与编码，以及发送页面来源、会话、防伪校验和最终状态。工具本地展示地址不等于目标来源，Submit 按钮不证明 CSRF 或 XSS；录像还需绑定最小 HTTP 证据。\n\n来源：[保存帖1](https://x.com/i/status/1528888750499143680)。'], ['experiment-design.md', '协议分析漏洞扫描和日志检索应按任务分工', '图将多个工具概括成网络安全工具，混用了扫描与日志搜索描述。\n\n区分产生探测请求、分析已有协议、聚合遥测和检索历史日志，记录各自产物及限制。界面统一或营销形容词不改变任务性质，工具介绍不能作为发现和覆盖证据。\n\n来源：[保存帖1](https://x.com/i/status/1528977244361990144)。'], ['source-audit.md', '生产 bundle 与 sourcemap 需保留版本及代码归属', '正文介绍分析 Webpack 产物、读取 JS 和通过 sourcemap 获取源码，没有完整外链实现。\n\n把运行 bundle、map 引用、源文件映射和部署时间关联，核 map 是否匹配实际版本。代码可见提供数据流候选，不能证明某路由可达或秘密有效；缺失原源码时标注映射范围，不推断完整仓库。\n\n来源：[保存帖1](https://x.com/i/status/1529015279895732224)、[保存帖2](https://x.com/i/status/1529516299168239617)、[保存帖3](https://x.com/i/status/1531532948268363778)。'], ['by-type/business-logic.md', '结账画面金额与实际结算参数分别证明', '图在外部 PoC 页面显示结账界面、金额、币种和修改按钮文字，未给最终交易记录。\n\n保留浏览器来源、真实提交请求、收款主体、金额单位与结算状态。界面可改写不等于账户余额已转移，也不自动支撑题名中的单击全余额影响。\n\n来源：[保存帖1](https://x.com/i/status/1529051919204814849)。'], ['by-type/info-secrets.md', '版本控制路径和代码搜索关键词仅定位待核内容', '正文列 Git/SVN 文件路径及配置、passwd、shadow 等搜索条件。\n\n分别确认端点实际返回、来源仓库/版本、字段用途和访问主体。文件名、关键词和 200 均不证明秘密有效或完整源码泄露；正常属性文件与认证材料分开，最小脱敏记录，不复制或使用值。\n\n来源：[保存帖1](https://x.com/i/status/1529097375322476545)、[保存帖2](https://x.com/i/status/1529488938137956353)。'], ['by-type/authn-session.md', '邮箱确认与二次验证必须约束同一服务端动作', '正文建议通过 API 使用未确认邮箱账户，或用 DELETE 绕过敏感操作的 2FA。\n\n固定自有账户状态、对象与动作，核网页与 API、各方法是否调用一致策略。API 可用不说明任何功能都必须邮箱确认，方法变化也不代表验证已绕过；需后续操作和持久状态证据。\n\n来源：[保存帖1](https://x.com/i/status/1529101706327474177)、[保存帖2](https://x.com/i/status/1529105231207882753)。'], ['by-type/lfi-path-traversal.md', 'ZIP 上传与 PHP 包含需核同一可达文件消费者', '正文提出由 ZIP 上传连接 LFI 与执行，未展示请求或结果。\n\n先核保存路径、归档条目、包装器支持以及应用执行的是读取还是包含。压缩包可上传不代表可包含其内容，文件字节读取也不等于 PHP 解释执行；缺少实际消费者时只保留分段验证方向。\n\n来源：[保存帖1](https://x.com/i/status/1529102417404432385)。'], ['by-type/ssrf.md', '多头回调标记需绑定来源与实际交互协议', '图在多个头分别放入不同外部标记，未展示对应回调结果。\n\n用自有有限样本区分哪个字段被哪一层消费，保留时间、解析/HTTP/邮件等协议和触发主体。唯一标记有助归因，但同时变化无法证明单个字段完整链；请求存在不等于已成立 SSRF。\n\n来源：[保存帖1](https://x.com/i/status/1529119797463568385)。'], ['by-type/authn-session.md', '本地响应和错误码变化还需服务端状态核对', '正文泛称请求/响应修改可造成严重问题，另建议替换改密响应或修改错误码。\n\n区分前端提示、导航参数与后端认证状态，用自有账户核后续受保护动作、原密码验证与持久变化。界面继续或错误文本改变不等于密码已变更，也不能由邮件受理推成 Critical。\n\n来源：[保存帖1](https://x.com/i/status/1529163840499458049)、[保存帖2](https://x.com/i/status/1530768001758203905)、[保存帖3](https://x.com/i/status/1531635826823774212)。'], ['by-type/csrf.md', '交易示意中的诱导点击需核身份与防伪绑定', '银行交易图把诱导链接、已登录交易页与转账结果相连。\n\n示意不证明真实交易成功。记录发起来源、会话携带、收款对象、金额及防伪校验，再用自有无害业务核最终状态；UI 欺骗与跨站请求是否接受分别解释。\n\n来源：[保存帖1](https://x.com/i/status/1529357081362386944)。'], ['by-type/file-upload.md', '双扩展名上传不保证服务器按脚本解释', '图示文件名从双扩展名变成脚本文件并产生连接，未展示保存和处理配置。\n\n逐段核接收、命名转换、存储路径、公开映射和解释器。上传成功或扩展名变化不等于可执行，示意连接也不能代替运行结果；按真实消费者约束影响。\n\n来源：[保存帖1](https://x.com/i/status/1529357081362386944)。'], ['by-type/cmd-injection-rce.md', '命令图的 shell 拼接与独立参数调用分别核对', '图由应用输入连接命令分隔与后续连接，没有实际请求结果。\n\n定位调用是否经过 shell、字符在哪次解析后进入命令，以及进程身份和输出来源。独立 argv 与命令字符串语义不同，正常探测输出不证明附加命令执行；用离线无害消费者验证数据流。\n\n来源：[保存帖1](https://x.com/i/status/1529357081362386944)。'], ['by-type/authn-session.md', 'root 对象形态与空数组不是通用认证身份', '图显示嵌套 root 对象中的认证字段、响应数据和 Cookie，正文另称空数组绕过。\n\n核实际 schema、解析类型、认证对象与响应主体，随后确认受限操作。字段名 root 不代表管理员角色，200 和 Cookie 发行也不能证明任意账户接管；图未展示的空数组路径不补造。\n\n来源：[保存帖1](https://x.com/i/status/1529407181711212544)。'], ['by-type/ssti.md', '算术结果需排除客户端模板及普通计算接口', '正文列不同算术表达式、方法和大量 SSTI 数量，没有响应证据。\n\n在自有离线样本核输入进入模板源码还是数据，确认求值位置、引擎与稳定对照。表达式被计算不自动代表服务器模板执行，更不推出 RCE；数量和预期奖励不作为确认依据。\n\n来源：[保存帖1](https://x.com/i/status/1529412124036014081)。'], ['by-type/request-smuggling.md', 'HTTP 差分模糊测试需记录每跳消息边界', '正文介绍基于语法的请求走私差分工具，未保存论文或实现全文。\n\n按自有多跳样本比较前后端接受字节、消息边界与后续请求归属，给差异保存完整证据。解析差异不等于实际请求串扰，外链题名也不补出算法或已验证受影响服务。\n\n来源：[保存帖1](https://x.com/i/status/1529507587342929921)。'], ['by-type/info-secrets.md', 'PII 的 OCR 和分类命中需回可见原图核实', '正文介绍用 OCR 和 CNN 搜索证件、照片与签名。\n\n记录原图可见范围、识别字段和模型分类，核误识别、裁剪与遮挡，最小化保存个人信息。分类标签不证明真实身份、有效证件或未授权公开；不能用机器结果代替实际原图审阅。\n\n来源：[保存帖1](https://x.com/i/status/1529569998255050756)。'], ['by-type/cmd-injection-rce.md', 'localhost 插件命令输出不能推广到所有 WordPress', '三段保存正文给相同插件路由与命令输出，显示 www-data 主体。\n\n保留本地部署、插件消费者、版本、认证及请求条件，区分 API 可达和具体命令执行。该有限输出不代表 WordPress 核心或任意部署可利用，也不说明获得系统管理员权限；不执行原命令。\n\n来源：[保存帖1](https://x.com/i/status/1529694086193508353)、[保存帖2](https://x.com/i/status/1530586904462245888)、[保存帖3](https://x.com/i/status/1530895209625624577)。'], ['discovery/passive-and-services.md', '归档 URL 主机提取应保留端口与原始引用', '图用 CDX 提取域名，一份输出含端口，另一份用 sed 删除协议、路径和 www。\n\n按 URL 结构分解 authority，保留原 URL、归档时间和规范化前后关系。collapse 与文本删除会丢失路径/端口或混淆真实主机；历史存在不代表当前有效与归属，不能声称枚举全部子域。\n\n来源：[保存帖1](https://x.com/i/status/1529710498127613952)。'], ['reporting.md', '复测批准和删除记录仍需同条件独立证据', '回复分别说明复测奖励及删除 NetDB 记录，其他邮件只称已解决。\n\n记录修复意图、部署与独立复测，核原 DNS/入口、消费者及等待条件。邮件支持流程状态，不能说明所有缓存与部署已消除影响；保留实际复测缺口，不补造成功结果。\n\n来源：[保存帖1](https://x.com/i/status/1529755050104573952)、[保存帖2](https://x.com/i/status/1529931474216050690)。'], ['by-type/info-secrets.md', '错误页版本信息与可利用缺陷分别证明', '邮件明确描述 400 页面出现 Nginx 版本并称重复，未保存实际错误响应。\n\n核异常路径、请求身份与真实返回字节，区分版本信息、补丁状态和可达攻击面。版本可见不直接证明未修复 CVE，重复处置也不替代机制证据；仅保留保存材料支持的披露范围。\n\n来源：[保存帖1](https://x.com/i/status/1529779013933096960)。'], ['by-type/authn-session.md', 'Cognito 挑战响应字段需由服务端绑定身份', '图展示 RespondToAuthChallenge、client ID 与 ChallengeResponses，字段大量遮挡，没有响应。\n\n核挑战会话、用户名、客户端与实际发行令牌主体，角色由应用服务端确定。请求字段中的 USER 不证明管理员角色或激活链接接管；不复制令牌或补出未展示结果。\n\n来源：[保存帖1](https://x.com/i/status/1529779355873710080)。'], ['discovery/records-and-incremental.md', 'JS 美化差分需同时保存原字节与获取条件', '图介绍变更监控、消息通知和美化 diff。\n\n保留原文件哈希、获取时间、会话/来源、版本及差分规则，区分语法格式变化与业务变化。美化可能隐藏字节差异，文件改变也不等于新漏洞；本次不发送通知或启动持续监控。\n\n来源：[保存帖1](https://x.com/i/status/1529781642650427394)。'], ['by-type/open-redirect.md', 'OTP 的 domain 参数受理不等于已发生跳转', '两图显示 OTP 生成请求中有 domain，响应仅 JSON success 和空 data，没有 Location 或最终落地页。\n\n追参数到实际发送链接、重定向处理与令牌消费者，并保留接收身份。请求受理不能证明任意跳转或账户接管；正文题名中的完整链未保存，不以成功值补全。\n\n来源：[保存帖1](https://x.com/i/status/1529832076748664832)、[保存帖2](https://x.com/i/status/1530130171142893569)。'], ['by-type/authn-session.md', '历史默认凭据清单需核自有部署配置和实际角色', '图分别是默认凭据报告题名与 Tomcat 清单，正文声称 dev 用户有高权限。\n\n把清单视为历史候选，核适用组件、初始化配置、当前自有身份与服务端角色。口令列表不代表所有版本默认有效，题名也不证明实际权限；不复制或尝试保存值，以自有配置核对。\n\n来源：[保存帖1](https://x.com/i/status/1529843449654034434)、[保存帖2](https://x.com/i/status/1530088761597612032)、[保存帖3](https://x.com/i/status/1530591750527811584)。'], ['discovery/records-and-incremental.md', 'Recon 数据库与 Repeater 分组需绑定身份和副作用', '正文建议数据库整理和 CLI/消息入口，图是端点树及含会话、防伪和验证码的重置请求，未给响应。\n\n按资产、操作、对象、身份和时间保存证据，分组只是整理，不授予批量重放许可。会话或一次性字段可能过期，状态变更请求需单独核执行及产物，避免把域名下所有记录当同一安全动作。\n\n来源：[保存帖1](https://x.com/i/status/1529861754590744578)、[保存帖2](https://x.com/i/status/1530082591411277824)。'], ['by-type/xss.md', '片段取值与 auxclick 需保留交互和脚本策略', '正文把片段字符串与 SVG auxclick 处理器连接，并称某次 WAF 放行。\n\n片段在浏览器侧消费，仍需实际事件交互、页面上下文、过滤结果及脚本策略。WAF 不看到片段不代表应用一定求值，事件处理器存在也不说明无交互执行；保留该次观察，不推广通用绕过。\n\n来源：[保存帖1](https://x.com/i/status/1529883784069492745)。'], ['source-audit.md', '历史 CVE 片段要保留中间解释器与配置条件', '图截取 ImageMagick 图形片段、CGI/Bash 示例及 TLS 缺陷章节，部分内容裁剪，标题混有 SSRF 与命令消费者。\n\n逐段追输入解析、外部 delegate、环境传递或库处理，核版本与配置。CVE 名称不说明当前部署满足条件，标签也不决定真实效果；不拼接裁剪处或执行归档代码，以具体消费者组织待核方法。\n\n来源：[保存帖1](https://x.com/i/status/1530182948288352257)。'], ['scope-and-rules.md', '子域图的主动被动分类应按真实网络动作', '完整脑图将词表、置换和虚拟主机列主动，但在被动分支也列端口、HTTP 和爬虫；正文另称证书一次收集全部子域。\n\n按实际是否向目标发送请求分类，区分第三方历史数据与目标验证。递归扩展每步重核范围，证书索引并非全量当前域集合；工具所属分支不能代替许可和覆盖证据。\n\n来源：[保存帖1](https://x.com/i/status/1530211052658769921)、[保存帖2](https://x.com/i/status/1530812067820630022)、[保存帖3](https://x.com/i/status/1531163384720203776)。'], ['experiment-design.md', 'Nmap 选项图需绑定版本权限和额外探测', '旧脑图列扫描方式、发现、时序和输出，将 -A 简化成操作系统检测。\n\n官方说明 -A 还启用版本检测、脚本和 traceroute；历史选项需按实际版本核。记录每种模式、权限和额外请求，主动性不由图名决定，参数设定也不能证明扫描完成。规范核验：[Nmap options](https://nmap.org/book/man-briefoptions.html)。\n\n来源：[保存帖1](https://x.com/i/status/1530212939579281408)、[保存帖2](https://x.com/i/status/1531855306518503424)。'], ['discovery/records-and-incremental.md', '扫描输出文件需保留格式运行边界与结束状态', '正文介绍日志输出，图列 normal/XML 等格式、追加与恢复。\n\n保存目标输入、版本、开始结束时间、退出状态和各格式产物引用，避免把旧追加或恢复记录当本轮独立结果。可见日志不保证全部请求完成，屏幕输出与保存文件分别核数量和失败。\n\n来源：[保存帖1](https://x.com/i/status/1530212939579281408)、[保存帖2](https://x.com/i/status/1531855306518503424)。'], ['cloud/cloud-misconfiguration.md', '子域清单与 S3 桶命名不是同一种对象', '正文将子域枚举文件直接交给桶扫描工具，并建议下载内容。\n\n核输入格式、桶/端点命名、区域、所属租户与许可，分别证明列表可见和对象可读。域名包含云特征不代表对应桶存在或公开；数量不能替代权限证据，不在资料提炼中枚举或下载云对象。\n\n来源：[保存帖1](https://x.com/i/status/1530401980065058817)。'], ['by-type/authn-session.md', '转发地址限流差异需固定账户处理器和时间', '图对比 429 与设置转发头后 200，响应称邮件已发送；部分字段遮挡，用户名/路径等对照不完整。\n\n固定自有账户、方法、Cookie、实际处理器和计数窗口，核可信来源与计数键。邮件受理不等于送达，多个变量变化不能归因单一头，更不能推成无条件暴力验证成功。\n\n来源：[保存帖1](https://x.com/i/status/1530510149999243264)。'], ['by-type/xxe.md', 'XML 实体进入错误页时失败状态仍可能泄露字节', '图中的外部实体进入响应 schema 字段，503 错误信息和 HTML 标题含 passwd 文本。\n\n核 XML 解析、实体加载与错误构造消费者，将状态和实际返回内容分开。503 不说明未消费输入，文件字节可见也不代表 RCE 或密码哈希；题名中的多目标与完整执行链没有保存，不扩大证据。\n\n来源：[保存帖1](https://x.com/i/status/1530514167278407681)。'], ['by-type/xss.md', 'URL 片段聚焦需核匹配元素与真实事件', '图把片段 ID 与 input 焦点处理器相连。\n\n核目标元素确实存在且可聚焦、导航时机、实际焦点变化与脚本策略。滚动和聚焦不保证所有浏览器触发同一事件，片段也不作为服务端请求路径；自有页面记录具体条件。规范核验：[HTML fragment navigation](https://html.spec.whatwg.org/multipage/browsing-the-web.html#scroll-to-the-fragment)。\n\n来源：[保存帖1](https://x.com/i/status/1530514231820443649)。'], ['by-type/authn-session.md', '重置令牌边界需保留发行消费重发与并发状态', '正文列移除、空值、过期、数组和并发条件，另一段仅提示收到代码及重发。\n\n按自有账户追发行主体、时效、一次性消费、重发是否撤销旧值和并发原子性。类型容错或收到代码不代表重置成功；有限离线状态样本核异常分支，不由清单补出普遍绕过。\n\n来源：[保存帖1](https://x.com/i/status/1530603835361660928)、[保存帖2](https://x.com/i/status/1530649092577173507)。'], ['by-type/sql-injection.md', '延时语法需绑定数据库方言与稳定对照', '正文分别以十秒页面响应称注入、以及 PostgreSQL 延时函数替代其他语法。\n\n定位具体方言、表达式位置和输入类型，使用自有离线消费者核语法，再记录稳定基线与差分。页面慢可能来自网络或业务，函数名可用不等于 SQL 到达数据库；不运行耗时探测或以一次延时确认注入。\n\n来源：[保存帖1](https://x.com/i/status/1530677618118369281)、[保存帖2](https://x.com/i/status/1531840636319457281)。'], ['targeted-fuzzing.md', '字典生成数量与 WAF 选项不是实际绕过结果', '图展示 LFI 字典、深度和 WAF 勾选，以及编码注意事项，输出称有 889 项。\n\n记录生成规则、原始值、每层编码/解码和实际消费者。生成项数不代表已执行或成功，重复编码可能改变有效输入；在自有小样本核转换，按消费者语法筛选，不能用复选框证明绕过。\n\n来源：[保存帖1](https://x.com/i/status/1530773159355379712)。'], ['experiment-design.md', '代理请求转 JavaScript 后要重新核浏览器限制', '图的扩展菜单可将所选实验室请求复制成 JavaScript。\n\n保留原方法、字节、会话和页面来源，核哪些头、Cookie 和请求体能由浏览器生成。文本转换不保证等价重放，原代理成功也不代表跨来源可读；生成与实际执行分别取证。\n\n来源：[保存帖1](https://x.com/i/status/1530773159355379712)。'], ['discovery/client-and-cloud.md', 'SSH 隧道示意需保留入口出口与许可', '图将本地客户端经 SSH 中转到另一服务，未展示真实连接结果。\n\n分别记录隧道认证、绑定地址、远端出口、DNS 位置和实际路由。连接中转会改变观察主体，不自动扩大测试范围；示意可达不证明通用防火墙绕过，当前只整理架构条件。\n\n来源：[保存帖1](https://x.com/i/status/1530775613782601732)。'], ['discovery/passive-and-services.md', '配置 IP 与出站地址需要核真实请求生产者', '正文概括 Cloudflare 入站/出站差异，并建议从 htaccess 内容抽地址再验证。\n\n区分代理入口、应用出站、解析器、NAT 和配置里的候选地址，保留生产者与时间。配置值未必当前可达，内网地址也不自动获许可；回调来源不能直接称源站，未保存前序步骤不补全。\n\n来源：[保存帖1](https://x.com/i/status/1530861060151975941)、[保存帖2](https://x.com/i/status/1530913992612663296)。'], ['by-type/xss.md', 'SOME 窗口关系需核调用时来源和具体动作', '完整图描述开启窗口、原窗口导航到目标、另一窗口经回调引用 opener 的 DOM 方法；正文提到同域或子域部署。\n\n按每次导航记录两个窗口来源、opener 是否保留、回调限制与 CSP，再核目标身份、动作及防伪状态。同站/子域不等于同源，已有回调能力也不能推广成所有 CSP 绕过或管理员执行。规范核验：[MDN 同源策略](https://developer.mozilla.org/en-US/docs/Web/Security/Defenses/Same-origin_policy)、[opener](https://developer.mozilla.org/en-US/docs/Web/API/Window/opener)。\n\n来源：[保存帖1](https://x.com/i/status/1531022887964098560)、[保存帖2](https://x.com/i/status/1531023890490826757)。'], ['source-audit.md', '特权候选标记需核文件权限及真实执行条件', '正文列自动提权工具，另一段搜索 root 所有且有 SUID 位的文件。\n\n将所有者、权限位、挂载条件、具体程序和输入消费者分别记录。候选列表不代表可利用，容器 socket 可写也需核真实服务权限；不执行归档提权代码，按自有环境追最终动作与进程身份。\n\n来源：[保存帖1](https://x.com/i/status/1531118666300858368)、[保存帖2](https://x.com/i/status/1531614155890909190)。'], ['by-type/file-upload.md', '图片尺寸资源影响需按解码预算分段评估', '正文建议上传极大像素图片并称 DDoS，没有运行证据。\n\n区分压缩字节、解码像素、帧数、并发与处理链，核限制在接收还是解码前生效。仅尺寸大不证明服务不可用，更不代表分布式攻击；自有隔离小样本只观察预算边界，不生成或上传耗尽资源的产物。\n\n来源：[保存帖1](https://x.com/i/status/1531168636223864833)。'], ['impact-and-acceptance.md', 'Windows 命令会话不证明域管理员控制', '图显示 handler、一次 Windows 命令会话和应用配置目录，正文称三小时域管理员。\n\n保留初始入口、进程主体、令牌与域权限证据，区分应用命令执行、本机管理员和域控制。会话打开及工作目录不足以补出后续身份提升，耗时不影响证据要求。\n\n来源：[保存帖1](https://x.com/i/status/1531195338106646528)。'], ['by-type/idor-access-control.md', '管理配置界面需核主体与持久动作权限', '图可见 Web 防火墙服务配置和端口，正文外链称从 JS 得到管理面板。\n\n界面可见只支持所显示配置的观察，继续核认证主体、读取范围与自有无害修改的最终持久状态。没有初始 JS 数据流和服务端动作证据时，不补成未授权管理权限。\n\n来源：[保存帖1](https://x.com/i/status/1531258957808824320)。'], ['source-audit.md', 'Ruby Kernel 是语言模块不是操作系统内核', '正文将 Kernel open、动态 send 和多种反序列化列为 Rails RCE 方向，图片只是文章封面。\n\n追不可信输入进入哪一方法、参数和类型，以及实际运行版本。Ruby Kernel 名称不代表内核级漏洞；动态分派也需具体可达方法与授权，不能从 API 名称推算执行结果。规范核验：[Ruby Kernel](https://docs.ruby-lang.org/en/master/Kernel.html)。\n\n来源：[保存帖1](https://x.com/i/status/1531289327069712385)。'], ['by-type/deserialization-rce.md', '序列化 Cookie 与 dump 题名不能证明秘密或 RCE', '一图只显示 API 请求的认证标志和长 data Cookie，正文另称 Java dump 暴露秘密；另一正文列多种 Ruby 解析器。\n\n先确定真实编码、格式、解析 API 和安全模式，追类型实例化与字段如何进入身份判断。客户端标志不能当服务端可信状态，编码字符串也不是 dump 内容；没有响应、秘密字段或执行产物时不补造完整链。\n\n来源：[保存帖1](https://x.com/i/status/1531289327069712385)、[保存帖2](https://x.com/i/status/1531546977246162944)。'], ['discovery/web-and-api.md', 'PostgREST 文档中的 RPC 需核实际数据库角色权限', '图显示 Swagger 文档、版本字符串、绑定地址、根描述接口与一项 RPC 的参数 schema。\n\n区分文档生成、路由实际可达、请求认证主体和数据库函数权限。0.0.0.0 是绑定信息，文档路径不代表任意 SQL 或管理员能力；部署版本和文档可见范围需单独核。\n\n来源：[保存帖1](https://x.com/i/status/1531374058427793413)。'], ['by-type/xss.md', '高频参数名字不等于当前 XSS 风险', '图列 25 个查询参数并引用历史来源，没有具体响应。\n\n把名字用作输入发现候选，记录真实使用位置、编码、输出上下文和浏览器消费者。排名缺少样本方法不能变成当前优先级，参数存在或反射也不保证执行。\n\n来源：[保存帖1](https://x.com/i/status/1531413314210873344)。'], ['by-type/info-secrets.md', '用户更新接口要分请求材料与非预期响应字段', '正文建议查看更新用户数据的接口，图仅奖励题名。\n\n绑定自有主体、对象和更新动作，区分客户端提交的数据、业务正常返回及额外敏感字段。赏金不证明全部字段泄露，需具体消费者和可见范围；最小脱敏记录，不尝试额外读取。\n\n来源：[保存帖1](https://x.com/i/status/1531517184370802688)。'], ['reporting.md', '例外奖励不能作为漏洞成立的通用依据', '回复明确称并非真正漏洞，但决定例外奖励。\n\n将奖励决策与技术结论分别记录，按可复现行为、边界失效和实际影响组织报告。金额不能替代这些证据，单项目例外也不构成其他项目的接受标准。\n\n来源：[保存帖1](https://x.com/i/status/1531597527165784064)。'], ['scope-and-rules.md', '范围字符串与模糊条目需按资产和动作解释', '正文区分通配域与单个域，并询问未明确列入或排除的条目。\n\n保存项目当前原文、域名边界、协议/端口与动作限制，明确范围变更时间。表面相似写法不能自动互换，未列出资产不默认获许可；资料整理可继续，实际验证必须落在已有明确授权。\n\n来源：[保存帖1](https://x.com/i/status/1531688859536396288)、[保存帖2](https://x.com/i/status/1531690982261006337)。'], ['discovery/web-and-api.md', '分号路径变化需核路由规范化和响应媒体类型', '正文给 Nginx/Tomcat 路径转换，另称给 JSON 端点附 HTML 后缀可在 Firefox 执行。\n\n逐跳核原路径、参数段、最终处理器和真实响应类型。同路径后缀可能改变服务端路由或协商，不能靠 URL 文字认定浏览器已把 JSON 当 HTML；还需内容、嗅探限制和 DOM 证据。规范核验：[MDN Content-Type](https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Content-Type)。\n\n来源：[保存帖1](https://x.com/i/status/1531696610606039041)、[保存帖2](https://x.com/i/status/1531700538370408450)、[保存帖3](https://x.com/i/status/1531736205569712129)、[保存帖4](https://x.com/i/status/1532294383881449474)。'], ['reporting.md', '选择器截图需绑定页面状态与原始响应', '正文介绍按 CSS 选择器截图，未保存实现全文。\n\n保存 URL、时间、身份、页面加载状态和裁剪选择器，并关联最小请求响应。截图提供可见区域证据，不能证明未截图部分、后台状态或完整业务覆盖；避免把渲染成功当漏洞确认。\n\n来源：[保存帖1](https://x.com/i/status/1531742311713054720)。'], ['discovery/records-and-incremental.md', '代理解压视图需保留原字节及变换说明', '图片在链接清单中实际给 gzip/deflate 解压选项提示，并以历史默认状态说明。\n\n分别保存原始传输、Content-Encoding、解码层次和编辑后字节，核当前工具配置。可读文本可能是解压产物，不能用显示长度代替原请求；历史默认提示不推广到当前版本，变换后的重放需重新核消费者。\n\n来源：[保存帖1](https://x.com/i/status/1531700040351494144)。'], ['experiment-design.md', 'headless 模板版本命中与浏览器执行证据分层', '图显示 localhost 的 headless 模板命中、引擎/模板版本及另一图的发布清单。\n\n记录实际加载模板、浏览器状态、匹配规则和原始产物。发布列表不代表所有模板执行，Medium 标签或版本链接也不代替脚本执行；外链全文按用户口径覆盖，未保存实现不补全。\n\n来源：[保存帖1](https://x.com/i/status/1531942772105682946)。']]
ids={pid for row in json.loads((W/"batch-0131.json").read_text()) for pid in row["post_ids"]}
urls=[pid for _,_,body in facets for pid in re.findall(r"https://x\.com/i/status/(\d+)",body)]
assert len(urls)==102 and all(pid in ids for pid in urls)
assert len({title for _,title,_ in facets})==len(facets)
grouped=defaultdict(list)
for f,title,body in facets:
 p=T/"references"/f
 assert p.is_file() and ("## "+title) not in p.read_text(),(f,title)
 grouped[p].append("\n\n## "+title+"\n\n"+body+"\n")
community=T/"references/research/community-distillation.md"
marker="\n## 首轮提炼范围与未采纳内容\n"
c=community.read_text();assert c.count(marker)==1
routes=[]
for f,title,body in facets:
 summary=body.split("\n")[0].split("。")[0]+"。"
 summary=summary.replace("|","｜")
 assert "|" not in summary and "\n" not in summary
 routes.append(f"| {title} | {summary} | [方法条目](../{f}) |")
for p,parts in grouped.items():p.write_text(p.read_text()+"".join(parts))
community.write_text(c.replace(marker,"\n"+"\n".join(routes)+"\n"+marker,1))
print("Added",len(facets),"facets/routes to",len(grouped),"topics;",len(urls),"batch-bound URLs")

